import{H as e,V as t,et as n,j as r}from"./chunks/framework.CW0zsFMp.js";import{Uo as i}from"./chunks/assets.BxHYjuf8.js";var a=JSON.parse(`{"title":"性能分析","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/performance-analysis.md","filePath":"mysql/performance-analysis.md"}`),o={name:`mysql/performance-analysis.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[e(`<h1 id="性能分析" tabindex="-1">性能分析 <a class="header-anchor" href="#性能分析" aria-label="Permalink to “性能分析”">​</a></h1><h2 id="_1-查看执行频次" tabindex="-1">1.查看执行频次 <a class="header-anchor" href="#_1-查看执行频次" aria-label="Permalink to “1.查看执行频次”">​</a></h2><p>MySQL客户端连接成功后，通过<code>show [session|global] status</code>命令可以提供服务器状态信息，通过以下指令可以查看当前数据库的 INSERT, UPDATE, DELETE, SELECT 访问频次</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SESSION</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> STATUS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Com_______&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;(7个下划线)</span></span></code></pre></div><h2 id="_2-慢查询日志" tabindex="-1">2.慢查询日志 <a class="header-anchor" href="#_2-慢查询日志" aria-label="Permalink to “2.慢查询日志”">​</a></h2><p>慢查询日志记录了所有执行时间超过指定参数（long_query_time，单位：秒，默认10秒）的所有SQL语句的日志。</p><p>查看慢查询日志开关状态（ON为开启，OFF为关闭）</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;slow_query_log&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>启用慢查询日志（重启后失效）</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> slow_query_log </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ON&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>MySQL的慢查询日志默认没有开启，需要在MySQL的配置文件（/etc/my.cnf）中配置如下信息（重启后不会失效）</p><p>1.开启慢查询日志开关</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">slow_query_log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span></code></pre></div><p>2.设置慢查询日志的时间（例如2秒），SQL语句执行时间超过2秒，就会视为慢查询，记录慢查询日志</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">long_query_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span></code></pre></div><ul><li><p>在执行这两条命令前，需要以管理员身份打开慢查询日志文件，具体操作可以上网搜索</p></li><li><p>更改后记得重启MySQL服务，日志文件位置：/var/lib/mysql/localhost-slow.log</p></li></ul><h2 id="_3-profile" tabindex="-1">3.profile <a class="header-anchor" href="#_3-profile" aria-label="Permalink to “3.profile”">​</a></h2><p>show profile 能在做SQL优化时帮我们了解时间都耗费在哪里。通过 have_profiling 参数，能看到当前 MySQL 是否支持 profile 操作</p><p>查看当前 MySQL 是否支持 profile 操作</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @@have_profiling;</span></span></code></pre></div><p>查看当前profiling是否开启</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @@profiling;</span></span></code></pre></div><p>profiling 默认关闭，可以通过set语句在session/global级别开启 profiling</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiling </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>查看所有语句的耗时</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show profiles;</span></span></code></pre></div><p>查看指定query_id（SQL语句的编号）的SQL语句各个阶段的耗时</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">profile</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> query query_id;</span></span></code></pre></div><p>查看指定query_id（SQL语句的编号）的SQL语句CPU的使用情况</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cpu </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> query query_id;</span></span></code></pre></div><h2 id="_4-explain" tabindex="-1">4.explain <a class="header-anchor" href="#_4-explain" aria-label="Permalink to “4.explain”">​</a></h2><p>EXPLAIN 或者 DESC 命令获取 MySQL 如何执行 SELECT 语句的信息，包括在 SELECT 语句执行过程中表如何连接和连接的顺序</p><p>语法（直接在select语句之前加上关键字 explain / desc）</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXPLAIN|</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 字段列表 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名 HWERE 条件;</span></span></code></pre></div><p><img src="`+i+`" alt="f430ee9948224187941e96cf53f10048png" width="1997" height="243"></p><h3 id="explain-各字段含义" tabindex="-1">EXPLAIN 各字段含义: <a class="header-anchor" href="#explain-各字段含义" aria-label="Permalink to “EXPLAIN 各字段含义:”">​</a></h3><ul><li><p><strong>id</strong>：select 查询的序列号，表示查询中执行 select 子句或者操作表的顺序（id相同，执行顺序从上到下（多表查询）；id不同，值越大越先执行（子查询））</p></li><li><p><strong>select_type</strong>：表示 SELECT 的类型，常见取值有 SIMPLE（简单表，即不使用表连接或者子查询）、PRIMARY（主查询，即外层的查询）、UNION（UNION中的第二个或者后面的查询语句）、SUBQUERY（SELECT/WHERE之后包含了子查询）等</p></li><li><p><strong>type</strong>：表示连接类型，性能由好到差的连接类型为 NULL、system、const、eq_ref、ref、range、index、all</p><ul><li><p>NULL：查询不访问任何表时出现，一般不会出现</p></li><li><p>system：当访问系统表或表中仅有一行记录时出现</p></li><li><p>const：使用 <code>PRIMARY KEY</code> 或者 <code>UNIQUE</code> 索引进行精确匹配，且只匹配到一行记录时会出现</p></li><li><p>eq_ref：在连接查询里使用 <code>PRIMARY KEY</code> 或者 <code>UNIQUE</code> 索引进行连接，且对于每个来自前面表的记录，在当前表中都能通过索引找到唯一匹配的记录时出现</p></li><li><p>ref：使用非唯一性索引查询时会出现</p></li><li><p>range：使用索引进行范围查询时出现</p></li><li><p>index：查询需要扫描整个索引树来获取数据时出现（不一定扫描全表）</p></li><li><p>all：扫描全表数据时出现</p></li></ul></li><li><p>从优到劣：NULL&gt; system &gt; const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL</p></li><li><p><strong>possible_key</strong>：可能应用在这张表上的索引，一个或多个</p></li><li><p><strong>Key</strong>：实际使用的索引，如果为 NULL，则没有使用索引</p></li><li><p><strong>Key_len</strong>：表示索引中使用的字节数，该值为索引字段最大可能长度，并非实际使用长度，在不损失精确性的前提下，长度越短越好</p></li><li><p><strong>rows</strong>：MySQL认为必须要执行的行数，在InnoDB引擎的表中，是一个估计值，可能并不总是准确的</p></li><li><p><strong>filtered</strong>：表示返回结果的行数占需读取行数的百分比，filtered的值越大越好</p></li></ul>`,37)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};